// Modern sculptural trophy — the shatter photo, embedded as base64.
// Why embedded: GitHub's push tool here is text-only, so a JPG/WebP
// file cannot be pushed by the assistant; a base64 string IS text, so
// it goes through the normal text push. The image is 1920x1280 WebP,
// q88 + sharpened (~66 KB, ~88 KB base64). If the user later pushes
// the file via normal git as /trophies/modern-sculptural.jpg, swap
// CUP_URL in TrophyShatter.tsx back to that path and delete this file.
export const SCULPTURAL_TROPHY_DATA_URI =
  'data:image/webp;base64,';
